/* =====================================================================
   app4_1_read_objects.sql   APP-4 stage 1: read function and procedures for the approval screens
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/procs/fn_request_actions.sql
     db/procs/usp_request_queue.sql
     db/procs/usp_request_detail.sql
     db/procs/usp_notification_list.sql
     db/procs/usp_request_form_options.sql
     db/procs/usp_equipment_requests.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app4_1_read_objects: 6 file(s) ===';

PRINT N'--- db/procs/fn_request_actions.sql';
EXEC (N'/* =====================================================================
   app.fn_request_actions       APP-4 helper (used by app.usp_request_queue and app.usp_request_detail,
                                so the screens'' buttons and the procedures'' refusals agree)
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_stage_eligibility, app.fn_return_rights, app.fn_requester_rights. Reads only.
   Tests: db/tests/t_request_reads.sql (scenario Q5 checks that every flag below matches what usp_request_decide,
   _resubmit and _cancel really do) and db/tests/t_request_approval_rules.sql (the 18 Nov rules).

   What may this person do with this request, and why not? The screens (S-2 checkboxes, S-3 buttons) show
   these answers; the procedures still enforce every rule themselves, so a wrong answer here could mislead a
   person but never let anything through.

   Input : @request_id, @actor_email (the signed-in person; blank or system:... gives "no" to everything).
   Output: one row per existing request (none for an unknown id):

     stage                   RESPONSIBLE or ACCOUNTABLE while the request waits for a decision, else NULL
     can_decide              the request waits for a decision AND the person is eligible for the stage: an active
                             member of the routed group holding the stage''s flag with a scope that covers the
                             profit centre, or an admin (app.fn_stage_eligibility). Approve, Reject, Return.
     decide_blocked_reason   why not (the words of app.usp_request_decide''s refusals), NULL when allowed
     can_approve             the same as can_decide since 18 Nov 2026 (the client allowed one person to approve both
                             stages, Q-479). Kept as its own column so the screens and the queue''s bulk tick box keep
                             one name for "may approve"; the failed-check block is shown by the screen from the checks.
     approve_blocked_reason  the decide reason
     decided_as              GROUP_MEMBER or ADMIN when can_decide (how the person qualifies), else NULL
     can_resubmit            app.fn_return_rights: RETURNED and the person is the recipient, or the return is
                             orphaned and the person is the submitter, a responsible-group member or an admin
     can_cancel              open, and the person raised it, or is an admin, or (RETURNED to a GROUP, a system
                             request) is a member of that group (app.usp_request_cancel)
     return_to_type/return_to  where a RETURN goes when the person picks nobody (the default), or, once RETURNED,
                             who it went to: the submitter for a field or manual request, the rule''s resolution
                             group for a rule request, the responsible group for a request the system raised; NULL
                             on a closed request. The people the person MAY pick are app.fn_return_candidates
                             (usp_request_detail result set 8).
   ===================================================================== */
CREATE OR ALTER FUNCTION app.fn_request_actions
(
    @request_id  bigint,
    @actor_email nvarchar(256)
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        r.request_id,
        st.stage,
        CAST(CASE WHEN z.decide_reason IS NULL THEN 1 ELSE 0 END AS bit)                         AS can_decide,
        CAST(z.decide_reason AS nvarchar(400))                                                   AS decide_blocked_reason,
        CAST(CASE WHEN z.decide_reason IS NULL THEN 1 ELSE 0 END AS bit)                         AS can_approve,
        CAST(z.decide_reason AS nvarchar(400))                                                   AS approve_blocked_reason,
        CAST(CASE WHEN z.decide_reason IS NOT NULL THEN NULL
                  WHEN el.is_group_member = 1 AND el.has_flag_in_scope = 1 THEN N''GROUP_MEMBER''
                  ELSE N''ADMIN'' END AS nvarchar(12))                                             AS decided_as,
        CAST(ISNULL(rr.can_resubmit, 0) AS bit)                                                  AS can_resubmit,
        CAST(CASE WHEN ac.is_person = 1
                   AND r.request_status <> N''APPROVED'' AND r.request_status <> N''REJECTED'' AND r.request_status <> N''CANCELLED''
                   AND (   LOWER(r.requested_by) = ac.a
                        OR ISNULL(me.can_manage_admin, 0) = 1
                        OR (r.request_status = N''RETURNED'' AND r.return_recipient_type = N''GROUP''
                            AND EXISTS (SELECT 1 FROM app.group_membership AS m2
                                        WHERE m2.group_key = r.return_recipient AND m2.is_active = 1 AND m2.user_email = ac.a)))
                  THEN 1 ELSE 0 END AS bit)                                                      AS can_cancel,
        CAST(rt.rtype AS nvarchar(10))                                                           AS return_to_type,
        CAST(rt.rrec  AS nvarchar(256))                                                          AS return_to
    FROM app.change_request AS r
    CROSS APPLY (SELECT CASE r.request_status WHEN N''PENDING_RESPONSIBLE'' THEN N''RESPONSIBLE''
                                              WHEN N''PENDING_ACCOUNTABLE'' THEN N''ACCOUNTABLE''
                                              ELSE NULL END AS stage) AS st
    CROSS APPLY (SELECT LOWER(LTRIM(RTRIM(@actor_email))) AS a) AS a0
    CROSS APPLY (SELECT a0.a AS a,
                        CASE WHEN a0.a IS NOT NULL AND CHARINDEX(N''@'', a0.a) > 1 AND LEFT(a0.a, 7) <> N''system:'' THEN 1 ELSE 0 END AS is_person,
                        CASE st.stage WHEN N''RESPONSIBLE'' THEN r.responsible_group
                                      WHEN N''ACCOUNTABLE'' THEN r.accountable_group
                                      ELSE NULL END AS grp) AS ac
    OUTER APPLY app.fn_stage_eligibility(ac.a, st.stage, ac.grp, r.profit_center_name) AS el
    OUTER APPLY app.fn_requester_rights(ac.a) AS me
    OUTER APPLY app.fn_return_rights(r.request_id, ac.a) AS rr
    CROSS APPLY (SELECT CASE
                     WHEN ac.is_person = 0
                         THEN N''Sign in as a person to decide.''
                     WHEN st.stage IS NULL
                         THEN N''The request is '' + r.request_status + N''; only a request that waits for a decision can be decided.''
                     WHEN el.is_eligible = 1
                         THEN NULL
                     WHEN el.is_group_member = 0
                         THEN N''You are not an active member of the group for this stage ('' + ISNULL(ac.grp, N''none'') + N'').''
                     ELSE N''No role of yours allows the '' + st.stage + N'' stage for '' + ISNULL(r.profit_center_name, N''this profit centre'') + N''.''
                     END AS decide_reason) AS z
    OUTER APPLY (SELECT TOP (1) b.resolution_group AS grp
                 FROM app.business_rules AS b
                 WHERE b.rule_id = r.source_rule_id AND b.rule_version = r.source_rule_version) AS br
    CROSS APPLY (SELECT CASE WHEN r.request_status = N''RETURNED''         THEN r.return_recipient_type
                             WHEN st.stage IS NULL                       THEN NULL
                             WHEN r.source_type = N''BUSINESS_RULE''       THEN N''GROUP''
                             WHEN LEFT(r.requested_by, 7) <> N''system:''  THEN N''USER''
                             ELSE N''GROUP'' END AS rtype,
                        CASE WHEN r.request_status = N''RETURNED''         THEN r.return_recipient
                             WHEN st.stage IS NULL                       THEN NULL
                             WHEN r.source_type = N''BUSINESS_RULE''       THEN ISNULL(br.grp, r.responsible_group)
                             WHEN LEFT(r.requested_by, 7) <> N''system:''  THEN r.requested_by
                             ELSE r.responsible_group END AS rrec) AS rt
    WHERE r.request_id = @request_id
);
');

PRINT N'--- db/procs/usp_request_queue.sql';
EXEC (N'/* =====================================================================
   app.usp_request_queue        APP-4, read path C (D-17); screen S-2 (approvals); function getRequestQueue
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.vw_request_queue, app.fn_request_actions. Reads only. Test: db/tests/t_request_reads.sql

   One tab of the approver''s work list, with the counts of all six tabs, in one call (one connection). The tabs
   are filters on the requests, using the groups of the person asking (FINAL PLAN/guide/app/S-02 section 2;
   "my queue" depends on who is asking, which is why the browser cannot filter a view by itself):

     RESPONSIBLE   waits for the responsible stage and is routed to a group the person is an active member of;
                   for an admin, every request waiting for that stage (an admin may decide any stage, 18 Nov 2026)
     ACCOUNTABLE   the same for the accountable stage
     RETURNED      status RETURNED and the person is the return recipient (the user, or a member of the group), or
                   the return is orphaned and the person may pick it up (app.fn_return_rights)
     APPROVED      every approved request (visibility is open: POC-APP-04)
     REJECTED      every rejected request
     MY_REQUESTS   raised by the person, in any status

   Input : @actor_email (a person), @tab, the filters (NULL / blank = no filter): @profit_center, @field_code,
           @rule_id (the rule that raised it), @min_age_hours (open requests at least that many hours old; ignored
           on APPROVED and REJECTED, which have no age), @note_only (1 = only requests that carry a note, the TBD
           ones), and the page: @offset (0 or more), @page_size (1 to 100).
   Order : pending and returned tabs oldest first (the longest wait on top); APPROVED, REJECTED and MY_REQUESTS
           newest change first. The request id is the last key, so a page boundary never repeats or skips a row.

   Four result sets, always in this order (an empty set when there is nothing):
     1  counts   one row: responsible_count, accountable_count, returned_count, approved_count, rejected_count,
                 mine_count (not narrowed by the filters)
     2  page     one row: total_matches (the tab''s rows after the filters, before paging)
     3  rows     the page: the columns of app.vw_request_queue plus can_approve (1 = the person may approve it and so
                 may tick it for a bulk approval: app.fn_request_actions)
     4  facets   what the filters can offer for this tab (ignoring the filters themselves): facet_kind
                 (PROFIT_CENTER, FIELD or RULE), facet_value, facet_label, n

   @only_set (testing aid, NULL = all): return only that numbered result set, so a test can read each set with
   INSERT ... EXEC, which cannot capture sets of different shapes. The functions never pass it.

   Refusals (THROW): 50311 unknown tab, 50312 page size outside 1 to 100, 50313 negative offset,
   50314 negative age, 50315 the queue is for a person (blank, no @, or a system: address).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_queue
    @actor_email   nvarchar(256),
    @tab           nvarchar(20),
    @profit_center nvarchar(40)  = NULL,
    @field_code    nvarchar(64)  = NULL,
    @rule_id       nvarchar(64)  = NULL,
    @min_age_hours int           = NULL,
    @note_only     bit           = 0,
    @offset        int           = 0,
    @page_size     int           = 50,
    @only_set      tinyint       = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @t nvarchar(20) = UPPER(LTRIM(RTRIM(@tab)));
    DECLARE @pc nvarchar(40) = NULLIF(LTRIM(RTRIM(@profit_center)), N'''');
    DECLARE @fc nvarchar(64) = NULLIF(LTRIM(RTRIM(@field_code)), N'''');
    DECLARE @rl nvarchar(64) = NULLIF(LTRIM(RTRIM(@rule_id)), N'''');

    IF @actor IS NULL OR CHARINDEX(N''@'', @actor) < 2 OR LEFT(@actor, 7) = N''system:''
        THROW 50315, N''The queue is shown to a person (an e-mail address).'', 1;
    IF @t IS NULL OR @t NOT IN (N''RESPONSIBLE'', N''ACCOUNTABLE'', N''RETURNED'', N''APPROVED'', N''REJECTED'', N''MY_REQUESTS'')
        THROW 50311, N''The tab must be RESPONSIBLE, ACCOUNTABLE, RETURNED, APPROVED, REJECTED or MY_REQUESTS.'', 1;
    IF @page_size IS NULL OR @page_size < 1 OR @page_size > 100
        THROW 50312, N''The page size must be from 1 to 100.'', 1;
    IF @offset IS NULL OR @offset < 0
        THROW 50313, N''The offset must be 0 or more.'', 1;
    IF @min_age_hours IS NOT NULL AND @min_age_hours < 0
        THROW 50314, N''The age must be 0 hours or more.'', 1;

    /* ---- the person''s groups ------------------------------------------------------------- */
    DECLARE @g TABLE (group_key nvarchar(64) NOT NULL PRIMARY KEY);
    INSERT INTO @g (group_key)
    SELECT m.group_key
    FROM app.group_membership AS m
    JOIN app.security_group AS sg ON sg.group_key = m.group_key AND sg.is_active = 1
    WHERE m.is_active = 1 AND m.user_email = @actor;

    /* an admin may decide every stage of every request (client, 18 Nov 2026), so both pending tabs list them all */
    DECLARE @is_admin bit = ISNULL((SELECT TOP (1) x.can_manage_admin FROM app.fn_requester_rights(@actor) AS x), 0);

    /* ---- every request with the tabs it belongs to, for this person -------------------------- */
    DECLARE @all TABLE
    (
        request_id        bigint        NOT NULL PRIMARY KEY,
        in_resp           bit           NOT NULL,
        in_acc            bit           NOT NULL,
        in_ret            bit           NOT NULL,
        in_app            bit           NOT NULL,
        in_rej            bit           NOT NULL,
        in_mine           bit           NOT NULL,
        is_open           bit           NOT NULL,
        profit_center_name nvarchar(40) NULL,
        field_code        nvarchar(64)  NULL,
        source_rule_id    nvarchar(64)  NULL,
        note              nvarchar(200) NULL,
        requested_at_utc  datetime2(3)  NOT NULL,
        updated_at_utc    datetime2(3)  NOT NULL
    );
    INSERT INTO @all (request_id, in_resp, in_acc, in_ret, in_app, in_rej, in_mine, is_open,
                      profit_center_name, field_code, source_rule_id, note, requested_at_utc, updated_at_utc)
    SELECT r.request_id, f.in_resp, f.in_acc, f.in_ret, f.in_app, f.in_rej, f.in_mine, f.is_open,
           r.profit_center_name, r.field_code, r.source_rule_id, r.note, r.requested_at_utc, r.updated_at_utc
    FROM app.change_request AS r
    CROSS APPLY
    (
        SELECT
            CAST(CASE WHEN r.request_status = N''PENDING_RESPONSIBLE''
                       AND (@is_admin = 1 OR EXISTS (SELECT 1 FROM @g AS g WHERE g.group_key = r.responsible_group)) THEN 1 ELSE 0 END AS bit) AS in_resp,
            CAST(CASE WHEN r.request_status = N''PENDING_ACCOUNTABLE''
                       AND (@is_admin = 1 OR EXISTS (SELECT 1 FROM @g AS g WHERE g.group_key = r.accountable_group)) THEN 1 ELSE 0 END AS bit) AS in_acc,
            CAST(CASE WHEN r.request_status <> N''RETURNED'' THEN 0
                      WHEN (r.return_recipient_type = N''USER'' AND LOWER(r.return_recipient) = @actor)
                        OR (r.return_recipient_type = N''GROUP'' AND EXISTS (SELECT 1 FROM @g AS g WHERE g.group_key = r.return_recipient)) THEN 1
                      WHEN EXISTS (SELECT 1 FROM app.fn_return_rights(r.request_id, @actor) AS rr WHERE rr.can_resubmit = 1) THEN 1
                      ELSE 0 END AS bit) AS in_ret,
            CAST(CASE WHEN r.request_status = N''APPROVED'' THEN 1 ELSE 0 END AS bit) AS in_app,
            CAST(CASE WHEN r.request_status = N''REJECTED'' THEN 1 ELSE 0 END AS bit) AS in_rej,
            CAST(CASE WHEN LOWER(r.requested_by) = @actor THEN 1 ELSE 0 END AS bit) AS in_mine,
            CAST(CASE WHEN r.request_status = N''APPROVED'' OR r.request_status = N''REJECTED'' OR r.request_status = N''CANCELLED''
                      THEN 0 ELSE 1 END AS bit) AS is_open
    ) AS f
    WHERE f.in_resp = 1 OR f.in_acc = 1 OR f.in_ret = 1 OR f.in_app = 1 OR f.in_rej = 1 OR f.in_mine = 1;

    /* ---- 1 counts (the six tabs, not narrowed by the filters) ------------------------------- */
    IF @only_set IS NULL OR @only_set = 1
    SELECT
        CAST(ISNULL(SUM(CAST(a.in_resp AS int)), 0) AS int) AS responsible_count,
        CAST(ISNULL(SUM(CAST(a.in_acc  AS int)), 0) AS int) AS accountable_count,
        CAST(ISNULL(SUM(CAST(a.in_ret  AS int)), 0) AS int) AS returned_count,
        CAST(ISNULL(SUM(CAST(a.in_app  AS int)), 0) AS int) AS approved_count,
        CAST(ISNULL(SUM(CAST(a.in_rej  AS int)), 0) AS int) AS rejected_count,
        CAST(ISNULL(SUM(CAST(a.in_mine AS int)), 0) AS int) AS mine_count
    FROM @all AS a;

    /* ---- the chosen tab, then the filters ---------------------------------------------------- */
    DECLARE @tabrows TABLE
    (
        request_id bigint NOT NULL PRIMARY KEY,
        profit_center_name nvarchar(40) NULL, field_code nvarchar(64) NULL, source_rule_id nvarchar(64) NULL,
        note nvarchar(200) NULL, is_open bit NOT NULL, requested_at_utc datetime2(3) NOT NULL, updated_at_utc datetime2(3) NOT NULL
    );
    INSERT INTO @tabrows (request_id, profit_center_name, field_code, source_rule_id, note, is_open, requested_at_utc, updated_at_utc)
    SELECT a.request_id, a.profit_center_name, a.field_code, a.source_rule_id, a.note, a.is_open, a.requested_at_utc, a.updated_at_utc
    FROM @all AS a
    WHERE (CASE @t WHEN N''RESPONSIBLE'' THEN a.in_resp WHEN N''ACCOUNTABLE'' THEN a.in_acc WHEN N''RETURNED'' THEN a.in_ret
                   WHEN N''APPROVED'' THEN a.in_app WHEN N''REJECTED'' THEN a.in_rej ELSE a.in_mine END) = 1;

    DECLARE @oldest_first bit = CASE WHEN @t IN (N''RESPONSIBLE'', N''ACCOUNTABLE'', N''RETURNED'') THEN 1 ELSE 0 END;
    DECLARE @ignore_age bit = CASE WHEN @t IN (N''APPROVED'', N''REJECTED'') THEN 1 ELSE 0 END;

    DECLARE @hit TABLE
    (
        request_id bigint NOT NULL PRIMARY KEY,
        k1 bigint NOT NULL,
        k2 bigint NOT NULL
    );
    INSERT INTO @hit (request_id, k1, k2)
    SELECT x.request_id,
           CASE WHEN @oldest_first = 1 THEN x.stamp ELSE -x.stamp END,
           CASE WHEN @oldest_first = 1 THEN x.request_id ELSE -x.request_id END
    FROM
    (
        SELECT t.request_id,
               DATEDIFF_BIG(second, CAST(''2000-01-01'' AS datetime2(3)), CASE WHEN @oldest_first = 1 THEN t.requested_at_utc ELSE t.updated_at_utc END) AS stamp
        FROM @tabrows AS t
        WHERE (@pc IS NULL OR t.profit_center_name = @pc)
          AND (@fc IS NULL OR t.field_code = @fc)
          AND (@rl IS NULL OR t.source_rule_id = @rl)
          AND (@note_only IS NULL OR @note_only = 0 OR t.note IS NOT NULL)
          AND (@min_age_hours IS NULL OR @min_age_hours = 0 OR @ignore_age = 1
               OR (t.is_open = 1 AND DATEDIFF(hour, t.requested_at_utc, SYSUTCDATETIME()) >= @min_age_hours))
    ) AS x;

    /* ---- 2 the size of the filtered tab ------------------------------------------------------ */
    IF @only_set IS NULL OR @only_set = 2
    SELECT CAST(COUNT(*) AS int) AS total_matches FROM @hit;

    /* ---- 3 the page ------------------------------------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 3
    SELECT
        q.request_id, q.request_ref, q.request_status, q.approval_stage, q.entity_type, q.equipment_id, q.equipment_number,
        q.functional_location, q.equipment_tag_number, q.profit_center_name, q.field_code, q.field_label, q.sap_field,
        q.old_value, q.new_value, q.reason, q.note, q.source_type, q.source_rule_id, q.source_rule_version, q.source_label,
        q.requested_by, q.requested_at_utc, q.detected_at_utc, q.responsible_group, q.accountable_group,
        q.return_recipient_type, q.return_recipient, q.age_hours, q.photo_count, q.updated_at_utc,
        CAST(ISNULL(ac.can_approve, 0) AS bit) AS can_approve
    FROM @hit AS h
    JOIN app.vw_request_queue AS q ON q.request_id = h.request_id
    OUTER APPLY app.fn_request_actions(q.request_id, @actor) AS ac
    ORDER BY h.k1, h.k2
    OFFSET @offset ROWS FETCH NEXT @page_size ROWS ONLY;

    /* ---- 4 what the filters can offer for this tab ------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 4
    SELECT f.facet_kind, f.facet_value, f.facet_label, f.n
    FROM
    (
        SELECT CAST(N''PROFIT_CENTER'' AS nvarchar(14)) AS facet_kind, CAST(t.profit_center_name AS nvarchar(64)) AS facet_value,
               CAST(t.profit_center_name AS nvarchar(100)) AS facet_label, CAST(COUNT(*) AS int) AS n
        FROM @tabrows AS t
        WHERE t.profit_center_name IS NOT NULL
        GROUP BY t.profit_center_name
        UNION ALL
        SELECT N''FIELD'', CAST(t.field_code AS nvarchar(64)), CAST(ISNULL(fc2.label, t.field_code) AS nvarchar(100)), CAST(COUNT(*) AS int)
        FROM @tabrows AS t
        LEFT JOIN app.field_catalog AS fc2 ON fc2.field_code = t.field_code
        WHERE t.field_code IS NOT NULL
        GROUP BY t.field_code, fc2.label
        UNION ALL
        SELECT N''RULE'', CAST(t.source_rule_id AS nvarchar(64)), CAST(t.source_rule_id AS nvarchar(100)), CAST(COUNT(*) AS int)
        FROM @tabrows AS t
        WHERE t.source_rule_id IS NOT NULL
        GROUP BY t.source_rule_id
    ) AS f
    ORDER BY f.facet_kind, f.facet_label;
END
');

PRINT N'--- db/procs/usp_request_detail.sql';
EXEC (N'/* =====================================================================
   app.usp_request_detail       APP-4, read path C (D-17); screen S-3 (request detail); function getRequestDetail
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.vw_request_detail, app.vw_request_event, app.vw_equipment_request, app.fn_request_checks,
   app.fn_request_actions and the gold views. Reads only. Test: db/tests/t_request_reads.sql

   Everything the request screen needs for ONE request, in one call (one connection instead of seven round
   trips). Eight result sets, always in this order (an empty set when there is nothing to show):

     1  request   app.vw_request_detail, one row: the queue columns, then class_code, route_id, creation_comment,
                  last_decision_by / _at_utc, merge_outcome, merged_at_utc, golden_version_id, exported_at_utc,
                  evolve_batch_id, evolve_row_number
     2  events    app.vw_request_event, oldest first (the Audit tab), plus three values read from the event''s JSON
                  (the long JSON itself is not sent): decided_as (GROUP_MEMBER or ADMIN), same_person_both_stages
                  (the second approval came from the person who did the first), returned_to (a RETURNED event''s
                  recipient)
     3  related   the other requests on the same heater, or at the same functional location (FLOC), open ones first,
                  newest first, at most 50, each with the overlap count of app.vw_equipment_request
     4  route     the approval route that was applied (0 rows when none matched)
     5  gold      the golden record now: the heater (or FLOC) and the current gold value of the requested field,
                  so the approver sees what the requester''s "old value" is compared with
     6  checks    the six live approval checks as the approver would see them (same rows as app.usp_request_checks)
     7  viewer    what @actor_email may do: can_decide / can_approve with their reasons, can_resubmit, can_cancel,
                  who a RETURN goes to by default with a readable label, the stage, and decided_as
                  (app.fn_request_actions)
     8  return_to who the person may pick in the Return dialog (app.fn_return_candidates): user_email, display_name,
                  relation (SUBMITTER, RESPONSIBLE_GROUP, ACCOUNTABLE_GROUP, YOU), is_you; empty unless the
                  person may decide the request now

   The evidence snapshot (event_details_json of the CREATED event, nvarchar(max)) is read by app.usp_request_evidence.
   Open visibility (POC-APP-04): everybody may read every request; what a person may DO is the viewer row, and the
   procedures enforce it again.

   @only_set (testing aid, NULL = all): return only that numbered result set, so a test can read each set with
   INSERT ... EXEC, which cannot capture sets of different shapes. The functions never pass it.

   Refusal (THROW): 50301 no such request.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_detail
    @request_id  bigint,
    @actor_email nvarchar(256),
    @only_set    tinyint = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    DECLARE @etype nvarchar(10), @eq int, @floc nvarchar(40), @field nvarchar(64);
    SELECT @etype = r.entity_type, @eq = r.equipment_id, @floc = r.functional_location, @field = r.field_code
    FROM app.change_request AS r
    WHERE r.request_id = @request_id;
    IF @etype IS NULL
        THROW 50301, N''That request does not exist.'', 1;

    /* ---- 1 the request ------------------------------------------------------------------ */
    IF @only_set IS NULL OR @only_set = 1
    SELECT d.*
    FROM app.vw_request_detail AS d
    WHERE d.request_id = @request_id;

    /* ---- 2 its history ------------------------------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 2
    SELECT e.event_id, e.event_type, e.approval_stage, e.actor, e.actor_group, e.occurred_at_utc, e.comments, e.status_from, e.status_to,
           CAST(JSON_VALUE(x.event_details_json, ''$.decided_as'') AS nvarchar(12)) AS decided_as,
           CAST(CASE WHEN JSON_VALUE(x.event_details_json, ''$.same_person_both_stages'') = N''true'' THEN 1 ELSE 0 END AS bit) AS same_person_both_stages,
           CAST(CASE WHEN e.event_type = N''RETURNED'' THEN JSON_VALUE(x.event_details_json, ''$.return_recipient'') END AS nvarchar(256)) AS returned_to
    FROM app.vw_request_event AS e
    JOIN app.change_request_event AS x ON x.event_id = e.event_id
    WHERE e.request_id = @request_id
    ORDER BY e.occurred_at_utc, e.event_id;

    /* ---- 3 related requests ---------------------------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 3
    SELECT TOP (50)
        q.request_id, q.request_ref, q.request_status, q.is_open, q.equipment_id, q.functional_location, q.field_code,
        q.field_label, q.source_label, q.requested_at_utc, q.other_open_requests_same_field
    FROM app.vw_equipment_request AS q
    WHERE q.request_id <> @request_id
      AND (   (@etype = N''EQUIPMENT'' AND (q.equipment_id = @eq OR (q.equipment_id IS NULL AND q.functional_location = @floc)))
           OR (@etype = N''FLOC'' AND q.functional_location = @floc))
    ORDER BY q.is_open DESC, q.requested_at_utc DESC, q.request_id DESC;

    /* ---- 4 the route that was applied ------------------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 4
    SELECT ro.route_id, ro.entity_type, ro.request_action, ro.field_or_characteristic, ro.class_scope, ro.responsible_role, ro.accountable_role
    FROM app.approval_route AS ro
    WHERE ro.route_id = (SELECT r.route_id FROM app.change_request AS r WHERE r.request_id = @request_id);

    /* ---- 5 the golden record now (exactly one result set, from whichever branch applies) ----- */
    IF @only_set IS NULL OR @only_set = 5
    BEGIN
    IF @etype = N''EQUIPMENT''
    BEGIN
        SELECT
            CAST(N''EQUIPMENT'' AS nvarchar(10))            AS entity_type,
            e.equipment_number, e.equipment_description, e.equipment_tag_number, e.functional_location, e.floc_description,
            e.equip_class, e.profit_center_name, e.manufacturer, e.model_number, e.manufacturer_serial_number,
            e.equipment_user_status, e.golden_version_id, e.last_changed_at_utc,
            CAST(fv.current_value AS nvarchar(400))       AS field_current_value,
            CAST(fv.unit AS nvarchar(20))                 AS field_unit
        FROM gold.vw_equipment_current AS e
        OUTER APPLY (SELECT TOP (1) x.current_value, x.unit
                     FROM gold.vw_equipment_field_current AS x
                     WHERE x.equipment_id = e.equipment_id AND x.field_code = @field) AS fv
        WHERE e.equipment_id = @eq;
    END
    ELSE
    BEGIN
        SELECT
            CAST(N''FLOC'' AS nvarchar(10))                 AS entity_type,
            CAST(NULL AS nvarchar(18))                    AS equipment_number,
            CAST(NULL AS nvarchar(40))                    AS equipment_description,
            CAST(NULL AS nvarchar(30))                    AS equipment_tag_number,
            l.functional_location, l.floc_description,
            CAST(NULL AS nvarchar(30))                    AS equip_class,
            l.profit_center_name,
            CAST(NULL AS nvarchar(30))                    AS manufacturer,
            CAST(NULL AS nvarchar(20))                    AS model_number,
            CAST(NULL AS nvarchar(30))                    AS manufacturer_serial_number,
            CAST(NULL AS nvarchar(30))                    AS equipment_user_status,
            l.golden_version_id, l.last_changed_at_utc,
            CAST(CASE WHEN @field = N''FLOC_CLASS'' THEN l.floc_class END AS nvarchar(400)) AS field_current_value,
            CAST(NULL AS nvarchar(20))                    AS field_unit
        FROM gold.vw_floc_current AS l
        WHERE l.functional_location = @floc;
    END
    END

    /* ---- 6 the live approval checks ----------------------------------------------------------- */
    IF @only_set IS NULL OR @only_set = 6
    SELECT c.check_order, c.check_code, c.check_status, c.message, c.checked_at_utc
    FROM app.fn_request_checks(@request_id, @actor) AS c
    ORDER BY c.check_order;

    /* ---- 7 what this person may do ------------------------------------------------------------ */
    IF @only_set IS NULL OR @only_set = 7
    SELECT
        a.can_decide, a.decide_blocked_reason, a.can_approve, a.approve_blocked_reason, a.can_resubmit, a.can_cancel,
        a.return_to_type, a.return_to,
        CAST(CASE WHEN a.return_to_type = N''USER'' THEN ISNULL(i.display_name, a.return_to)
                  WHEN a.return_to_type = N''GROUP'' THEN ISNULL(g.display_name, a.return_to)
                  ELSE a.return_to END AS nvarchar(256)) AS return_to_label,
        a.stage,
        a.decided_as
    FROM app.fn_request_actions(@request_id, @actor) AS a
    OUTER APPLY (SELECT TOP (1) p.display_name FROM app.principal_identity AS p
                 WHERE p.user_email = a.return_to AND p.is_active = 1) AS i
    OUTER APPLY (SELECT TOP (1) sg.display_name FROM app.security_group AS sg
                 WHERE sg.group_key = a.return_to) AS g;

    /* ---- 8 who a Return may be sent to (the dialog''s picker; empty when this person may not decide) ---------- */
    IF @only_set IS NULL OR @only_set = 8
    SELECT c.user_email, c.display_name, c.relation, c.is_you
    FROM app.fn_return_candidates(@request_id, @actor) AS c
    WHERE EXISTS (SELECT 1 FROM app.fn_request_actions(@request_id, @actor) AS a WHERE a.can_decide = 1)
    ORDER BY c.sort_order, c.display_name, c.user_email;
END
');

PRINT N'--- db/procs/usp_notification_list.sql';
EXEC (N'/* =====================================================================
   app.usp_notification_list    APP-4, read path C (D-17); the notification bell (S-12 is APP-8); function getMyNotifications
   Single statement per file; CREATE OR ALTER, safe to run again.
   Reads only. Test: db/tests/t_request_reads.sql

   The in-app notifications of one person (queued by app.usp_notification_enqueue since APP-3): how many are not
   yet marked read, and the newest ones. Notifications are personal data, so this is read through a function with
   the caller''s own e-mail, never through the connector. Marking them read is APP-8 (until then the count only
   grows).

   Two result sets, always in this order:
     1  one row: unread_count
     2  the newest @limit notifications, newest first: notification_id, topic, request_id, request_ref, title, body,
        created_at_utc, is_read

   @only_set (testing aid, NULL = all): return only that numbered result set, so a test can read each set with
   INSERT ... EXEC, which cannot capture sets of different shapes. The functions never pass it.

   Refusals (THROW): 50321 limit outside 1 to 50, 50322 the list is for a person (blank, no @, or a system: address).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_notification_list
    @actor_email nvarchar(256),
    @limit       int = 20,
    @only_set    tinyint = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    IF @actor IS NULL OR CHARINDEX(N''@'', @actor) < 2 OR LEFT(@actor, 7) = N''system:''
        THROW 50322, N''Notifications belong to a person (an e-mail address).'', 1;
    IF @limit IS NULL OR @limit < 1 OR @limit > 50
        THROW 50321, N''The limit must be from 1 to 50.'', 1;

    IF @only_set IS NULL OR @only_set = 1
    SELECT CAST(COUNT(*) AS int) AS unread_count
    FROM app.notification AS n
    WHERE n.recipient_email = @actor AND n.read_at_utc IS NULL;

    IF @only_set IS NULL OR @only_set = 2
    SELECT TOP (@limit)
        n.notification_id, n.topic, n.request_id, r.request_ref, n.title, n.body, n.created_at_utc,
        CAST(CASE WHEN n.read_at_utc IS NULL THEN 0 ELSE 1 END AS bit) AS is_read
    FROM app.notification AS n
    LEFT JOIN app.change_request AS r ON r.request_id = n.request_id
    WHERE n.recipient_email = @actor
    ORDER BY n.created_at_utc DESC, n.notification_id DESC;
END
');

PRINT N'--- db/procs/usp_request_form_options.sql';
EXEC (N'/* =====================================================================
   app.usp_request_form_options  APP-4, read path C (D-17); the request dialog on S-5; function getRequestFormOptions
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.fn_requester_rights. Reads only. Test: db/tests/t_request_reads.sql

   What the "Request change" dialog needs besides the field catalogue (which the browser reads through the connector):
   the drop-down values of the LIST fields, whether this person may submit requests at all, and which fields they may
   not ask for by hand. Showing this only saves a person from filling in a form that app.usp_request_create would
   refuse (50107 not allowed to submit, 50113 admin-only field); the procedure still enforces both.

   Three result sets, always in this order:
     1  allowed values   field_code, allowed_value, display_order: the active values of app.field_allowed_value for
                         active catalogue fields
     2  one row          can_submit (registered and holding a role with can_submit_requests), is_admin (can_manage_admin)
     3  blocked fields   field_code, reason: the admin-only fields (setting ADMIN_ONLY_FIELDS, seed 0109) when the person
                         is not an admin; no rows for an admin

   @only_set (testing aid, NULL = all): return only that numbered result set, so a test can read each set with
   INSERT ... EXEC, which cannot capture sets of different shapes. The functions never pass it.

   Refusal (THROW): 50331 the options are for a person (blank, no @, or a system: address).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_request_form_options
    @actor_email nvarchar(256),
    @only_set    tinyint = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @actor nvarchar(256) = LOWER(LTRIM(RTRIM(@actor_email)));
    IF @actor IS NULL OR CHARINDEX(N''@'', @actor) < 2 OR LEFT(@actor, 7) = N''system:''
        THROW 50331, N''The request options belong to a person (an e-mail address).'', 1;

    DECLARE @submit bit = 0, @admin bit = 0;
    SELECT @submit = rr.can_submit_requests, @admin = rr.can_manage_admin
    FROM app.fn_requester_rights(@actor) AS rr;

    IF @only_set IS NULL OR @only_set = 1
    SELECT a.field_code, a.allowed_value, a.display_order
    FROM app.field_allowed_value AS a
    JOIN app.field_catalog AS c ON c.field_code = a.field_code AND c.is_active = 1
    WHERE a.is_active = 1
    ORDER BY a.field_code, a.display_order, a.allowed_value;

    IF @only_set IS NULL OR @only_set = 2
    SELECT CAST(ISNULL(@submit, 0) AS bit) AS can_submit, CAST(ISNULL(@admin, 0) AS bit) AS is_admin;

    IF @only_set IS NULL OR @only_set = 3
    SELECT CAST(LTRIM(RTRIM(s.value)) AS nvarchar(64)) AS field_code,
           CAST(N''Only an admin may ask to change this field by hand.'' AS nvarchar(200)) AS reason
    FROM STRING_SPLIT(ISNULL((SELECT x.setting_value FROM app.app_setting AS x WHERE x.setting_key = N''ADMIN_ONLY_FIELDS''), N''''), N'','') AS s
    WHERE LTRIM(RTRIM(s.value)) <> N'''' AND ISNULL(@admin, 0) = 0
    ORDER BY LTRIM(RTRIM(s.value));
END
');

PRINT N'--- db/procs/usp_equipment_requests.sql';
EXEC (N'/* =====================================================================
   app.usp_equipment_requests   APP-4, read path C (D-17); screen S-5 ("Requests on this heater"); function getEquipmentRequests
   Single statement per file; CREATE OR ALTER, safe to run again.
   Needs: app.vw_equipment_request and gold.vw_equipment_current. Reads only. Test: db/tests/t_request_reads.sql

   Every change request that touches one heater: its own requests, and the requests about the functional location
   (FLOC) it sits at, open ones first, newest first, with the overlap count of app.vw_equipment_request (how many
   OTHER open requests target the same field). Open visibility (POC-APP-04): everybody may read them.

   Two result sets, always in this order:
     1  one row: total_count
     2  the newest 100 rows: request_id, request_ref, request_status, is_open, equipment_id, functional_location,
        field_code, field_label, source_label, requested_at_utc, other_open_requests_same_field
   @only_set (testing aid, NULL = all): return only that numbered result set, so a test can read each set with
   INSERT ... EXEC, which cannot capture sets of different shapes. The functions never pass it.
   An unknown heater gives a count of 0 and no rows: it is not an error here (the heater screen reports a
   missing heater itself).
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_equipment_requests
    @equipment_id int,
    @only_set     tinyint = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @floc nvarchar(40) =
        (SELECT TOP (1) e.functional_location FROM gold.vw_equipment_current AS e WHERE e.equipment_id = @equipment_id);

    IF @only_set IS NULL OR @only_set = 1
    SELECT CAST(COUNT(*) AS int) AS total_count
    FROM app.vw_equipment_request AS q
    WHERE q.equipment_id = @equipment_id
       OR (q.equipment_id IS NULL AND @floc IS NOT NULL AND q.functional_location = @floc);

    IF @only_set IS NULL OR @only_set = 2
    SELECT TOP (100)
        q.request_id, q.request_ref, q.request_status, q.is_open, q.equipment_id, q.functional_location, q.field_code,
        q.field_label, q.source_label, q.requested_at_utc, q.other_open_requests_same_field
    FROM app.vw_equipment_request AS q
    WHERE q.equipment_id = @equipment_id
       OR (q.equipment_id IS NULL AND @floc IS NOT NULL AND q.functional_location = @floc)
    ORDER BY q.is_open DESC, q.requested_at_utc DESC, q.request_id DESC;
END
');

PRINT N'=== end of app4_1_read_objects ===';
